import { addCollection, Icon as IconifyIcon } from '@iconify/react';
import phosphor from '../../generated/phosphor-icons.json';

// Offline Phosphor subset generated by scripts/build-icons.mjs, so no Iconify API requests.
addCollection(phosphor);

export interface IconProps {
  /** Phosphor icon name, e.g. "ph:github-logo-bold" */
  name: `ph:${string}`;
  size?: number | string;
  className?: string;
  /** Accessible label; omit for decorative icons (default). */
  label?: string;
}

export function Icon({ name, size = '1.15em', className, label }: IconProps) {
  return (
    <IconifyIcon
      icon={name}
      width={size}
      height={size}
      className={className ? `icon ${className}` : 'icon'}
      aria-hidden={label ? undefined : true}
      aria-label={label}
      role={label ? 'img' : undefined}
    />
  );
}
